import type { WinLineData } from '../services/WinEvaluator';
import { ReelContainer } from '../reels/ReelContainer';
import { GameRound } from './GameRound';

export class WinEvaluationRound extends GameRound {
    private readonly animationDurationMs = 2800;

    constructor(
        private readonly reelContainer: ReelContainer,
        private readonly wins: WinLineData[],
    ) {
        super();
    }

    public async init(): Promise<void> {
        const winningSymbols = new Set<ReturnType<ReelContainer['getSymbolAt']>>();

        for (const win of this.wins) {
            for (const symbolData of win.symbols) {
                const symbol = this.reelContainer.getSymbolAt(symbolData.reelId, symbolData.rowId);
                if (symbol && symbol.id === symbolData.symbolId) {
                    winningSymbols.add(symbol);
                }
            }
        }

        const symbolsToAnimate = [...winningSymbols].filter((symbol) => symbol !== undefined);
        if (symbolsToAnimate.length === 0) {
            return;
        }

        for (const symbol of symbolsToAnimate) {
            symbol.showWin();
        }

        await new Promise<void>((resolve) => setTimeout(resolve, this.animationDurationMs));
    }
}