import { GameEvents } from "../core/EventDispather";
import { Game } from "../Game";
import { ReelAnimationManager } from "../reels/ReelAnimationManager";
import { GameState } from "../models/GameStateModel";

export class GamePlayRequest {
    private animationManager!: ReelAnimationManager;
    public game: Game;

    constructor( game: Game,reelAnimationManager: ReelAnimationManager    ) {
        this.game = game;
        this.animationManager = reelAnimationManager;
        this.game.eventDispatcher.on(GameEvents.USER_CLICK_SPIN, () => {
            this.onSpinButtonClick();
        });
    }
    public async onSpinButtonClick(): Promise<void> {
        if (!this.game.stateModel.canSpin()) {
            console.warn('[Guard]: Game is currently busy!');
            return;
        }

        this.game.stateModel.transitionTo(GameState.SPINNING);
     
        const spinAnimation = this.animationManager.spinReels();
        try {
            const response = await this.game.networkService.requestSpinData({ betAmount: 10, lines: 20 });
            this.game.roundWin = response.totalWin;
            await spinAnimation;
            this.game.eventDispatcher.emit(GameEvents.START_WIN_PRESENTATION);
        
            if (response.freeSpinsTriggered) {
                console.log("Triggering Free Spins Feature Animation!");
            }
        } catch (error) {
            this.animationManager.cancelSpin();
            await spinAnimation;
            const err = error as Error;
            console.error("Spin Request Failed:", err.message);
        }
        finally {
            this.game.stateModel.transitionTo(GameState.IDLE);
        }

    }
}