import * as PIXI from 'pixi.js';
import { Game } from '../Game';
import { GameState } from '../models/GameStateModel';
import { ResponsiveGameContainer } from '../views/ResponsiveGameContainer';
import { ReelAnimationManager } from '../reels/ReelAnimationManager';
import { ReelContainer } from '../reels/ReelContainer';
import { SymbolManager } from '../symbols/SymbolManager';
import { AssetLoader } from '../assets/AssetLoader';
import { ButtonPanel } from '../views/ButtonPanel';
import { GamePlayRequest } from '../services/GamePlayRequest';
import { GameEvents } from '../core/EventDispather';
import { BottomBar } from '../views/BottomBar';
import { GameRound } from '../rounds/GameRound';
import { WinEvaluationRound } from '../rounds/WinEvaluationRound';
import { SymbolConfig } from '../symbols/SymbolConfig';
import { SpinResponse } from '../services/NetworkService';
import { SpineWinEffect } from '../winCelebration/SpineWinEffect';

export class GameScene extends PIXI.Container {
    public game: Game;
    public sceneId: string = 'Base_Game';
    protected gameLayer: ResponsiveGameContainer;
    protected buttonPanel!: ButtonPanel;
    protected bottomBar!: BottomBar;
    private winCelebration!: SpineWinEffect;

    private symbolManager!: SymbolManager;
    private animationManager!: ReelAnimationManager;
    private reelContainer!: ReelContainer;
    private autoPlayEnabled = false;
    private autoPlayTimer: ReturnType<typeof setTimeout> | undefined;
    protected gameRounds: GameRound[] = [];
    constructor(
        game: Game
    ) {
        super();
        this.game = game;
        this.game.stage.addChild(this);

        this.gameLayer = new ResponsiveGameContainer();
        this.addChild(this.gameLayer);
        this.addComponents();
    }
    protected addComponents(): void {
        // Add components to the scene here
        this.registerBackgrounds();
        this.registerGameTitle();
        this.registerSymbols();

        this.registerReelContainers();
        this.registerButtonPanels();
        this.registerCommands();
        this.registerBottomBar();
        this.buttonPanel.position.set(0, 550);
        const reelGridWidth = this.reelContainer.reels.length * SymbolConfig.REEL_WIDTH;
        this.reelContainer.position.set((this.gameLayer.gameAreaW - reelGridWidth) / 2, 180);
        this.bottomBar.position.set(0, 640);
        this.winCelebration = new SpineWinEffect();

        this.winCelebration.position.set(this.gameLayer.gameAreaW / 2, this.gameLayer.gameAreaH / 2);
        this.gameLayer.addChild(this.winCelebration);

    }
    protected registerBottomBar(): void {
        // Register bottom panels here
        this.bottomBar = new BottomBar();
        this.gameLayer.addChild(this.bottomBar);
    }
    protected registerCommands(): void {
        // Register scene backgrounds here
        const spinRequestCommand = new GamePlayRequest(this.game, this.animationManager);
        this.game.eventDispatcher.on(GameEvents.STATE_CHANGED, () => {
            if (this.game.stateModel.currentState === GameState.SPINNING) {
                this.game.balance -= this.game.bet;
                this.bottomBar.setBalance(this.game.balance);
                this.bottomBar.hide();
            } else if (this.game.stateModel.currentState === GameState.IDLE && this.autoPlayEnabled) {
                this.scheduleAutoPlaySpin();
            }
        });
        this.game.eventDispatcher.on(GameEvents.START_WIN_PRESENTATION, this.startWinPresentaion, this)
        this.game.eventDispatcher.on(GameEvents.SPIN_RESPONSE_RECEIVED, this.injectReponse, this);
    }
    protected injectReponse(gameResponse: SpinResponse): void {
        this.game.activeResponse = gameResponse;
        this.game.roundWin = this.game.activeResponse?.totalWin;
    }
    protected registerBackgrounds(): void {
        // Register scene backgrounds here
    }
    protected registerGameTitle(): void {
        const title = new PIXI.Text({
            text: 'Slot Demo',
            style: new PIXI.TextStyle({
                fill: '#ffd166',
                fontSize: 36,
                fontWeight: 'bold',
            }),
        });
        title.anchor.set(0.5);
        title.position.set(350, 95);
        this.gameLayer.addChild(title);
    }
    protected registerSymbols(): void {
        this.symbolManager = new SymbolManager();
        const spriteKey: string = "symbols-sheet";
        const winSpriteKey: string = "symbolsWin";

        this.symbolManager.registerSymbol(0, new PIXI.Sprite(AssetLoader.getTexture(spriteKey, "symbol_santa_hat")),
            new PIXI.AnimatedSprite([AssetLoader.getTexture(winSpriteKey, "symbol_santa_hat")]),
        );
        this.symbolManager.registerSymbol(1, new PIXI.Sprite(AssetLoader.getTexture(spriteKey, "symbol_candy_cane")),
            new PIXI.AnimatedSprite([AssetLoader.getTexture(winSpriteKey, "symbol_candy_cane")]),
        );
        this.symbolManager.registerSymbol(2, new PIXI.Sprite(AssetLoader.getTexture(spriteKey, "symbol_bauble")),
            new PIXI.AnimatedSprite([AssetLoader.getTexture(winSpriteKey, "symbol_bauble")]),
        );
        this.symbolManager.registerSymbol(3, new PIXI.Sprite(AssetLoader.getTexture(spriteKey, "symbol_gingerbread")),
            new PIXI.AnimatedSprite([AssetLoader.getTexture(winSpriteKey, "symbol_gingerbread")]),
        );
        this.symbolManager.registerSymbol(4, new PIXI.Sprite(AssetLoader.getTexture(spriteKey, "symbol_stocking")),
            new PIXI.AnimatedSprite([AssetLoader.getTexture(winSpriteKey, "symbol_stocking")]),
        );
        this.symbolManager.registerSymbol(5, new PIXI.Sprite(AssetLoader.getTexture(spriteKey, "symbol_bell")),
            new PIXI.AnimatedSprite([AssetLoader.getTexture(winSpriteKey, "symbol_bell")]),
        );
        this.symbolManager.registerSymbol(6, new PIXI.Sprite(AssetLoader.getTexture(spriteKey, "symbol_snow_globe")),
            new PIXI.AnimatedSprite([AssetLoader.getTexture(winSpriteKey, "symbol_snow_globe")]),
        );
        this.symbolManager.registerSymbol(7, new PIXI.Sprite(AssetLoader.getTexture(spriteKey, "symbol_star_tree")),
            new PIXI.AnimatedSprite([AssetLoader.getTexture(winSpriteKey, "symbol_star_tree")]),
        );
        // Register scene symbols here
    }
    protected registerButtonPanels(): void {
        // Register button panels here
        this.buttonPanel = new ButtonPanel(
            () => { void this.toggleBackground(); },
            (enabled) => this.setAutoPlayEnabled(enabled)

        );
        this.gameLayer.addChild(this.buttonPanel);
    }
    protected registerReelContainers(): void {
        // Register reel containers here
        this.reelContainer = new ReelContainer(this.symbolManager, 5, 3);
        this.animationManager = new ReelAnimationManager(this.reelContainer);
        this.gameLayer.addChild(this.reelContainer);
    }

    public init(): void {
        this.game.stateModel.transitionTo(GameState.IDLE);
    }
    private async toggleBackground(): Promise<void> {
        // this.currentBackground = this.currentBackground === 'snow' ? 'summer' : 'snow';
        // this.hudView.setBackgroundLabel(this.currentBackground);
        // await this.backgroundUI.transitionToScene(this.currentBackground);
    }
    private setAutoPlayEnabled(enabled: boolean): void {
        this.autoPlayEnabled = enabled;
        if (this.autoPlayTimer !== undefined) {
            clearTimeout(this.autoPlayTimer);
            this.autoPlayTimer = undefined;
        }
        if (enabled && this.game.stateModel.currentState === GameState.IDLE) {
            this.scheduleAutoPlaySpin();
        }
    }
    private scheduleAutoPlaySpin(): void {
        if (this.autoPlayTimer !== undefined) {
            clearTimeout(this.autoPlayTimer);
        }
        this.autoPlayTimer = setTimeout(() => {
            this.autoPlayTimer = undefined;
            if (this.autoPlayEnabled && this.game.stateModel.currentState === GameState.IDLE) {
                this.game.eventDispatcher.emit(GameEvents.USER_CLICK_SPIN);
            }
        }, 1000);
    }
    private async startWinPresentaion(): Promise<void> {
        this.game.stateModel.transitionTo(GameState.EVALUATING);
        this.gameRounds = [
            new WinEvaluationRound(this.reelContainer, this.game.activeResponse?.wins ?? [])
        ];
        for (const round of this.gameRounds) {
            await round.init();
        }
        this.bottomBar.setBalance(this.bottomBar.getBalance() + this.game.roundWin);
        if (this.game.roundWin > 0) {
            this.bottomBar.showWin(this.game.roundWin);
            void this.winCelebration.play();
        }

    }
}