import * as PIXI from 'pixi.js';

export class BottomBar extends PIXI.Container {
    private amountText: PIXI.Text;
    private balanceText!: PIXI.Text;
    private betText!: PIXI.Text;
    private balance = 1000;
    private bet = 1;

    constructor() {
        super();

        const background = new PIXI.Graphics();
        background.rect(0, 0, 700, 80);
        background.fill({ color: 0x000000 });
        this.addChild(background);

        this.balanceText = this.createValuePanel('BALANCE', this.formatCurrency(this.balance), 0);
        this.betText = this.createValuePanel('BET', this.formatCurrency(this.bet), 550, true);

        const title = new PIXI.Text({
            text: 'WIN',
            style: new PIXI.TextStyle({
                fill: '#ffd166',
                fontSize: 24,
                fontWeight: 'bold',
                align: 'center'
            })
        });
        title.anchor.set(0.5);
        title.position.set(350, 20);

        this.amountText = new PIXI.Text({
            text: '$0.00',
            style: new PIXI.TextStyle({
                fill: '#ffffff',
                fontSize: 30,
                fontWeight: 'bold',
                align: 'center'
            })
        });
        this.amountText.anchor.set(0.5);
        this.amountText.position.set(350, 52);
        this.amountText.visible = false;

        this.addChild(title, this.amountText);
    }
    public setBalance(value: number): void {
        this.balance = value;
        this.balanceText.text = this.formatCurrency(this.balance);
    }

    public setBet(value: number): void {
        this.bet = value;
        this.betText.text = this.formatCurrency(this.bet);
    }

    public showWin(amount: number): void {
        this.amountText.text = `$${amount.toFixed(2)}`;
        this.amountText.visible = true;
    }

    public hide(): void {
        this.amountText.text = '$0.00';
        this.amountText.visible = false;
    }
    private formatCurrency(value: number): string {
        return `$${value.toFixed(2)}`;
    }
    private createValuePanel(title: string, initialValue: string, x: number, rightAligned = false): PIXI.Text {
        const panel = new PIXI.Container();
        const background = new PIXI.Graphics();
        background.roundRect(0, 0, 150, 60, 10);
        background.fill({ color: 0x252b48 });
        background.stroke({ color: 0x596080, width: 1 });

        const titleText = new PIXI.Text({
            text: title,
            style: new PIXI.TextStyle({
                fill: '#aeb8d8',
                fontSize: 12,
                fontWeight: 'bold'
            })
        });
        if (rightAligned) {
            titleText.anchor.set(1, 0);
        }
        titleText.position.set(rightAligned ? 138 : 12, 6);

        const valueText = new PIXI.Text({
            text: initialValue,
            style: new PIXI.TextStyle({
                fill: '#ffffff',
                fontSize: 19,
                fontWeight: 'bold'
            })
        });
        if (rightAligned) {
            valueText.anchor.set(1, 0);
        }
        valueText.position.set(rightAligned ? 138 : 12, 27);

        panel.addChild(background, titleText, valueText);
        panel.position.set(x, 10);
        this.addChild(panel);
        return valueText;
    }
    public getBalance(): number {
        return this.balance;
    }

    public getBet(): number {
        return this.bet;
    }

}
