import * as PIXI from 'pixi.js';
import { EventDispather, GameEvents } from '../core/EventDispather';

export class ButtonPanel extends PIXI.Container {
    private spinButton!: PIXI.Container;
    private statusText!: PIXI.Text;
    private backgroundText!: PIXI.Text;
    private backgroundToggle!: PIXI.Container;
    private autoPlayText!: PIXI.Text;
    private autoPlayBackground!: PIXI.Graphics;
    private autoPlayEnabled = false;
    private eventBus = EventDispather.getInstance();

    constructor(
        private readonly onToggleBackground: () => void = () => { },
        private readonly onAutoPlayChange: (enabled: boolean) => void = () => { }
    ) {
        super();
        this.createStatusText();
        this.createSpinButton();
        this.createAutoPlayToggle();
        this.createBackgroundToggle();
        this.listenToEvents();
    }

    public setBackgroundLabel(name: 'snow' | 'summer'): void {
        this.backgroundText.text = `BACKGROUND: ${name.toUpperCase()}`;
    }

    public setBackgroundToggleVisible(visible: boolean): void {
        this.backgroundToggle.visible = visible;
        this.backgroundToggle.eventMode = visible ? 'static' : 'none';
        this.backgroundToggle.cursor = visible ? 'pointer' : 'default';
    }

    private createStatusText(): void {
        this.statusText = new PIXI.Text({
            text: '',
            style: new PIXI.TextStyle({
                fill: '#ffffff',
                fontSize: 22,
                fontWeight: 'bold'
            })
        });
        this.statusText.anchor.set(0.5, 0);
        this.statusText.position.set(350, -38);
        this.addChild(this.statusText);
    }

    private createSpinButton(): void {
        this.spinButton = new PIXI.Container();

        const bg = new PIXI.Graphics();
        bg.roundRect(0, 0, 140, 50, 8);
        bg.fill({ color: 0x00b894 });

        const txt = new PIXI.Text({
            text: 'SPIN',
            style: new PIXI.TextStyle({
                fill: '#ffffff',
                fontSize: 20,
                fontWeight: 'bold'
            })
        });
        txt.anchor.set(0.5);
        txt.position.set(70, 25);

        this.spinButton.position.set(550, 5);
        this.spinButton.addChild(bg, txt);
        this.setSpinEnabled(false);

        this.spinButton.on('pointerdown', () => {
            this.setSpinEnabled(false);
            this.eventBus.emit(GameEvents.USER_CLICK_SPIN);
        });

        this.addChild(this.spinButton);
    }

    private createAutoPlayToggle(): void {
        const button = new PIXI.Container();
        this.autoPlayBackground = new PIXI.Graphics();
        this.drawAutoPlayBackground();

        this.autoPlayText = new PIXI.Text({
            text: 'AUTOPLAY OFF',
            style: new PIXI.TextStyle({
                fill: '#ffffff',
                fontSize: 14,
                fontWeight: 'bold',
            }),
        });
        this.autoPlayText.anchor.set(0.5);
        this.autoPlayText.position.set(90, 25);

        button.position.set(10, 5);
        button.eventMode = 'static';
        button.cursor = 'pointer';
        button.addChild(this.autoPlayBackground, this.autoPlayText);
        button.on('pointerdown', () => {
            this.autoPlayEnabled = !this.autoPlayEnabled;
            this.autoPlayText.text = this.autoPlayEnabled ? 'AUTOPLAY ON' : 'AUTOPLAY OFF';
            this.drawAutoPlayBackground();
            this.onAutoPlayChange(this.autoPlayEnabled);
        });
        this.addChild(button);
    }

    private drawAutoPlayBackground(): void {
        this.autoPlayBackground.clear();
        this.autoPlayBackground.roundRect(0, 0, 180, 50, 8);
        this.autoPlayBackground.fill({ color: this.autoPlayEnabled ? 0x00b894 : 0x52627a });
    }

    private createBackgroundToggle(): void {
        const button = new PIXI.Container();
        const background = new PIXI.Graphics();
        background.roundRect(0, 0, 190, 50, 8);
        background.fill({ color: 0x52627a });

        this.backgroundText = new PIXI.Text({
            text: 'BACKGROUND: SNOW',
            style: new PIXI.TextStyle({
                fill: '#ffffff',
                fontSize: 13,
                fontWeight: 'bold',
            }),
        });
        this.backgroundText.anchor.set(0.5);
        this.backgroundText.position.set(95, 25);

        button.position.set(500, 5);
        button.eventMode = 'static';
        button.cursor = 'pointer';
        button.addChild(background, this.backgroundText);
        button.on('pointerdown', this.onToggleBackground);
        this.backgroundToggle = button;
        this.addChild(button);
        this.setBackgroundToggleVisible(false);
    }

    private listenToEvents(): void {
        this.eventBus.on(GameEvents.STATE_CHANGED, (state: string) => {
           // this.statusText.text = `Status: ${state}`;
            this.setSpinEnabled(state === 'IDLE');
        });
    }

    private setSpinEnabled(enabled: boolean): void {
        this.spinButton.eventMode = enabled ? 'static' : 'none';
        this.spinButton.cursor = enabled ? 'pointer' : 'default';
        this.spinButton.alpha = enabled ? 1 : 0.55;
    }
}