import * as PIXI from 'pixi.js';

import { SymbolManager } from '../symbols/SymbolManager';
import { SymbolConfig } from '../symbols/SymbolConfig';
import { ReelView } from './ReelView';

export class ReelContainer extends PIXI.Container {
    public reels: ReelView[] = [];

    constructor(
        symbolManager: SymbolManager,
        cols: number = 5,
        rows: number = 3,
        symbolHeight: number = SymbolConfig.SYMBOL_ROW_HEIGHT,
        reelWidth: number = SymbolConfig.REEL_WIDTH
    ) {
        super();
        this.initGrid(symbolManager, cols, rows, symbolHeight, reelWidth);
    }

    private initGrid(
        symbolManager: SymbolManager,
        cols: number,
        rows: number,
        symbolHeight: number,
        reelWidth: number
    ): void {
        this.removeChildren();
        this.reels = [];

        const background = new PIXI.Graphics();
        background.rect(0, 0, cols * reelWidth, rows * symbolHeight);
        background.fill({ color: 0x18213a });
        this.addChild(background);

        for (let c = 0; c < cols; c++) {
            // Updated: c ko as 'reelIndex' pass kar rahe hain
            const reel = new ReelView(symbolManager, c, rows, symbolHeight, reelWidth);
            reel.x = c * reelWidth;
            this.addChild(reel);
            this.reels.push(reel);
        }
    }

    public updateGrid(matrix: number[][]): void {
        this.reels.forEach((reel, colIndex) => {
            const columnValues = matrix[colIndex] ?? [];
            reel.updateSymbols(columnValues);
        });
    }

    public getSymbolAt(reelId: number, rowId: number): import('../symbols/SymbolView').SymbolView | undefined {
        return this.reels[reelId]?.getVisibleSymbol(rowId);
    }

    public resetWinSymbols(): void {
        for (const reel of this.reels) {
            for (const symbol of reel.symbolSprites) {
                symbol.showIdle();
            }
        }
    }
}