import * as PIXI from 'pixi.js';
import { AssetLoader } from '../assets/AssetLoader';
import { Spine } from '@pixi/spine-pixi';

const SPINE_ALIAS = 'win-star';

export class SpineWinEffect extends PIXI.Container {
    private spine?: Spine|null|undefined;

    constructor() {
        super();
        this.visible = false;
    }

    public async play(): Promise<void> {
        if (!this.spine) {
            this.spine = AssetLoader.getSpine(SPINE_ALIAS);
            
            if (!this.spine) {
                return;
            }

            this.spine.state.addListener({
                complete: () => {
                    this.visible = false;
                },
            });
            this.addChild(this.spine);
        }

        this.visible = true;
        this.spine.state.setAnimation(0, 'burst', false);
    }
}