import * as PIXI from 'pixi.js';
import { EventDispather, GameEvents } from '../core/EventDispather';

export class ResponsiveGameContainer extends PIXI.Container {
    constructor(
        public readonly gameAreaW: number = 700,
        public readonly gameAreaH: number = 720
    ) {
        super();
         EventDispather.getInstance().on(GameEvents.GAME_RESIZED, (SCREEN_WIDTH: number, SCREEN_HEIGHT: number) => {
                    this.resize(SCREEN_WIDTH, SCREEN_HEIGHT);
                });
    }

    public resize(viewportWidth: number, viewportHeight: number): void {
        const scale = Math.min(
            viewportWidth / this.gameAreaW,
            viewportHeight / this.gameAreaH
        );

        this.scale.set(scale);
        this.position.set(
            (viewportWidth - this.gameAreaW * scale) / 2,
            (viewportHeight - this.gameAreaH * scale) / 2
        );
    }
}
